	(204, 'conformance-ehrs-rle', 1, 'CapabilityStatement', 'valid', 'system', '2026-10-06 20:13:18', '<?xml version="1.0" encoding="UTF-8"?>

<CapabilityStatement xmlns="http://hl7.org/fhir">
  <id value="conformance-ehrs-rle"/>
  <meta>
    <versionId value="1"/>
    <lastUpdated value="2026-10-06T20:13:17.576-04:00"/>
