        <expression value="InitialPopulation1"/>
      </criteria>
    </population>
    <population>
      <code>
        <coding>
          <code value="denominator"/>
        </coding>
      </code>
      <criteria>
        <language value="text/cql"/>
        <expression value="Denominator1"/>
      </criteria>
    </population>
    <population>
      <code>
        <coding>
          <code value="denominator-exclusions"/>
        </coding>
      </code>
      <criteria>
        <language value="text/cql"/>
        <expression value="DenominatorExclusions1"/>
      </criteria>
    </population>
    <population>
